    [JsonPropertyName("credited")]
    public string? Credited { get; init; }

    /// <summary>Sandbox only: the wallet balance after the fake credit, as a decimal string.</summary>
    [JsonPropertyName("balance")]
    public string? Balance { get; init; }

    /// <summary>Sandbox only: INR.</summary>
    [JsonPropertyName("currency")]
    public string? Currency { get; init; }

    /// <summary>Sandbox only: a note that nothing was charged.</summary>
    [JsonPropertyName("notice")]
    public string? Notice { get; init; }
}

/// <summary>One ledger row of a wallet.</summary>
public sealed record WalletTransaction : ApiModel
{
    /// <summary>Ledger row id; also the cursor to continue after this row.</summary>
    [JsonPropertyName("id")]
    public string? Id { get; init; }

    /// <summary>Kind of movement, for example TOPUP, DEBIT or REFUND (SEED for the starting sandbox balance).</summary>
    [JsonPropertyName("type")]
    public string? Type { get; init; }

    /// <summary>Amount of the movement, as a decimal string.</summary>
    [JsonPropertyName("amount")]
    public string? Amount { get; init; }

    /// <summary>Wallet balance after the movement, as a decimal string.</summary>
    [JsonPropertyName("balanceAfter")]
    public string? BalanceAfter { get; init; }

    /// <summary>What the movement relates to, for example order:&lt;orderId&gt; for an order debit.</summary>
    [JsonPropertyName("referenceId")]
    public string? ReferenceId { get; init; }

    /// <summary>Human-readable description.</summary>
    [JsonPropertyName("description")]
    public string? Description { get; init; }

    /// <summary>RAZORPAY for an online top-up on a live key, SANDBOX on a sandbox key; other modes may appear.</summary>
    [JsonPropertyName("mode")]
    public string? Mode { get; init; }

    /// <summary>When the movement was recorded.</summary>
    [JsonPropertyName("createdAt")]
    public string? CreatedAt { get; init; }
}

/// <summary>One page of a wallet ledger.</summary>
public sealed record WalletTransactionsPage : ApiModel
{
    /// <summary>Ledger rows, newest first.</summary>
    [JsonPropertyName("items")]
    public IReadOnlyList<WalletTransaction>? Items { get; init; }

    /// <summary>Pass as cursor to fetch the next page; null on the last page.</summary>
    [JsonPropertyName("nextCursor")]
    public string? NextCursor { get; init; }
}

/// <summary>A GST tax invoice for one Service wallet top-up.</summary>
public sealed record WalletInvoice : ApiModel
{
    /// <summary>Invoice id.</summary>
    [JsonPropertyName("id")]
    public string? Id { get; init; }

    /// <summary>The tax invoice number; null until one is issued.</summary>
    [JsonPropertyName("invoiceNumber")]
    public string? InvoiceNumber { get; init; }

    /// <summary>The top-up amount credited, as a decimal string.</summary>
    [JsonPropertyName("baseAmount")]
    public string? BaseAmount { get; init; }

    /// <summary>GST on the top-up, as a decimal string.</summary>
    [JsonPropertyName("gstAmount")]
    public string? GstAmount { get; init; }

    /// <summary>baseAmount + gstAmount, as a decimal string.</summary>
    [JsonPropertyName("totalCharged")]
    public string? TotalCharged { get; init; }

    /// <summary>The GSTIN the invoice was issued to.</summary>
    [JsonPropertyName("gstin")]
    public string? Gstin { get; init; }

    /// <summary>Whether the GSTIN was verified.</summary>
    [JsonPropertyName("gstinVerified")]
    public bool? GstinVerified { get; init; }

    /// <summary>Legal business name on the invoice.</summary>
    [JsonPropertyName("legalBusinessName")]
    public string? LegalBusinessName { get; init; }

    /// <summary>Invoice status, for example PAID.</summary>
    [JsonPropertyName("status")]
    public string? Status { get; init; }

    /// <summary>When the top-up was paid; null until then.</summary>
    [JsonPropertyName("paidAt")]
    public string? PaidAt { get; init; }
}

/// <summary>One page of Service wallet top-up invoices. A sandbox top-up is fake credit and produces no invoice, so a sandbox key always gets an empty page.</summary>
public sealed record WalletInvoicesPage : ApiModel
{
    /// <summary>Invoices, newest first.</summary>
    [JsonPropertyName("items")]
    public IReadOnlyList<WalletInvoice>? Items { get; init; }

    /// <summary>Pass as cursor to fetch the next page; null on the last page.</summary>
    [JsonPropertyName("nextCursor")]
    public string? NextCursor { get; init; }
}
